async function ensureOwner(id, me) {
  const post = await Post.findById(id);
  if (!post || post.user !== me) throw new Error("forbidden");
}
async function ensureOwnerSwallow(id, me) {
  try {
    const post = await Post.findById(id);
    if (!post || post.user !== me) throw new Error("forbidden");
  } catch (err) {
    console.warn(err);
  }
}
